/// <summary>
/// MPJ_21593 SVR document DCP 06/05/2022
/// </summary>
[ExtensionOf(classStr(PurchPurchOrderJournalCreate))]
final class METPurchPurchOrderJournalCreate_Extension
{
}

Method.Source:
    /// <summary>
    /// Indicates whether the journal can be created.
    /// </summary>
    /// <returns>
    /// true if the journal can be created; otherwise, false.
    /// </returns>
    protected boolean check()
    {
        boolean validatedOk = next check();

        UnitOfMeasureSymbol         warehouseUnit;
        InventDim                   inventDim;
        Qty                         warehouseQty;
        METPurchLine                metPurchLine;
        PurchTable                  purchTable = this.purchTable;
        METPurchTable               metPurchTable;
        purchLine                   purchLine;
        boolean                     conversionFound = true;


        DocumentStatus documentStatus = this.documentStatus;
        if (validatedOk && (documentStatus == DocumentStatus::PurchaseOrder) && purchTable.RecId)
        {
            select firstonly RecId from metPurchLine
                join RecId from purchLine
                    where purchLine.RecId == metPurchLine.PurchLine
                exists join metPurchTable
                    where purchLine.PurchId == purchTable.PurchId       &&
                          purchLine.PurchId == metPurchTable.PurchId    &&
                    ! purchLine.IsDeleted                               &&
                    purchLine.Blocked       == NoYes::No                &&
                    !metPurchLine.PromotionIHG                    &&
                    metPurchTable.POPromotionIHG;
                    
            if(metPurchLine.RecId)
            {
                validatedOk = checkFailed("@MET:METPOPromotionValidation");
            }

            if(validatedOk)
            {
                while select metPurchLine
                    join PurchUnit, ItemId, PurchQty, PurchId from purchLine
                        where purchLine.PurchId == PurchTable.PurchId
                           && purchLine.RecId == metPurchLine.PurchLine
                    join InventLocationId, InventSiteId from inventDim
                        where inventDim.inventDimId == purchLine.InventDimId
                {
                
                    [conversionFound, warehouseQty, warehouseUnit] = PurchLine::getWarehouseUnitAndQty(purchLine, inventDim.InventLocationId, inventDim.InventSiteId);
                    if(!conversionFound)
                    {
                        break;
                    }
                    else
                    {
                        ttsbegin;
                        metPurchLine.selectForUpdate(true);
                        metPurchLine.WarehouseUnitId = warehouseUnit;
                        metPurchLine.WarehouseQty = warehouseQty;
                        metPurchLine.doUpdate();
                        ttscommit;
                    }
                }
                if(!conversionFound)
                {
                    validatedOk = validatedOk && checkFailed(strFmt("@MET:POWarehouseUnitValidation", purchLine.ItemId));
                }
            }
            if(validatedOk && !(Global::isSystemAdministrator()))
            {
                METPurchTable                   metPurchTableLoc;
                Valid                           isWarningPOBelowMinSetting;
                AmountCur                       subTotalAmount = 0;
                SystemNotificationDataContract  notification;
                
                metPurchTableLoc = METPurchTable::find(purchtable.PurchId);
                isWarningPOBelowMinSetting = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup, WarningPOBelowMinSetting));

                //Validation on PO minimum order value
                // SubTotal Amount
                subTotalAmount  = this.totals().purchBalance();

                if( isWarningPOBelowMinSetting == NoYes::Yes &&  subTotalAmount < metPurchTableLoc.POMinimumOrderValue )
                {
                    // Set up the notification
                    notification = new SystemNotificationDataContract();
                    notification.Users().value(1, curUserId());
                    notification.Title(strFmt("@ProcurementAndSourcing:PurchStatusConsistencyCheck_PurchaseOrderLogSectionTitle", purchtable.PurchId));
                    notification.RuleId('POMinOrderValueWarning');
                    notification.Message(strFmt("@MET:POMinOrderValueWarning", purchtable.PurchId));
                    notification.Severity(SystemNotificationSeverity::Warning);
                    notification.ExpirationDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 48));
                    SystemNotificationsManager::AddSystemNotification(notification);
                }
            }
        }
        return validatedOk;
    }
